insert into public.quests (questline_id, key, position, name, level_required, giver_external_id, summary, status, source_path, source_metadata) values ((select id from public.questlines where key = 'english_kingdom_maya'), 'q01_runaway_a', 0, 'The Runaway A', 1, 'teacher_maya', 'מאיה מברכת אתכם בממלכת האנגלית — האות A בורחת כי היא חושבת שהיא המלכה של כל האלף-בית!', 'complete', 'questlines\english_kingdom_maya\q01_runaway_a.yaml', '{"source_detail":{"giver_npc":"teacher_maya","id":"q01_runaway_a","level_required":1,"name":"The Runaway A","prerequisite":null,"summary":"מאיה מברכת אתכם בממלכת האנגלית — האות A בורחת כי היא חושבת שהיא המלכה של כל האלף-בית!"},"source_index_path":"questlines\\english_kingdom_maya\\_index.yaml"}'::jsonb) on conflict (questline_id, key) do update set position = excluded.position, name = excluded.name, level_required = excluded.level_required, giver_external_id = excluded.giver_external_id, summary = excluded.summary, status = excluded.status, source_path = excluded.source_path, source_metadata = excluded.source_metadata, updated_at = now();
insert into public.quests (questline_id, key, position, name, level_required, giver_external_id, summary, status, source_path, source_metadata) values ((select id from public.questlines where key = 'english_kingdom_maya'), 'q02_bee_bandit', 1, 'The Bee Bandit', 2, 'teacher_maya', 'דבורה שובבה גנבה את האות B מהשלט BEE — בלי B, הדבורים שוכחות איך לזמזם באנגלית!', 'complete', 'questlines\english_kingdom_maya\q02_bee_bandit.yaml', '{"source_detail":{"giver_npc":"teacher_maya","id":"q02_bee_bandit","level_required":2,"name":"The Bee Bandit","prerequisite":"q01_runaway_a","summary":"דבורה שובבה גנבה את האות B מהשלט BEE — בלי B, הדבורים שוכחות איך לזמזם באנגלית!"},"source_index_path":"questlines\\english_kingdom_maya\\_index.yaml"}'::jsonb) on conflict (questline_id, key) do update set position = excluded.position, name = excluded.name, level_required = excluded.level_required, giver_external_id = excluded.giver_external_id, summary = excluded.summary, status = excluded.status, source_path = excluded.source_path, source_metadata = excluded.source_metadata, updated_at = now();
insert into public.quests (questline_id, key, position, name, level_required, giver_external_id, summary, status, source_path, source_metadata) values ((select id from public.questlines where key = 'english_kingdom_maya'), 'q03_cat_on_c', 2, 'Cat on the C', 3, 'teacher_maya', 'החתול של מאיה ישב על האות C וכיווץ אותה לצורת קרואסון — עכשיו כולם קוראים לה ''כרוסון''!', 'complete', 'questlines\english_kingdom_maya\q03_cat_on_c.yaml', '{"source_detail":{"giver_npc":"teacher_maya","id":"q03_cat_on_c","level_required":3,"name":"Cat on the C","prerequisite":"q02_bee_bandit","summary":"החתול של מאיה ישב על האות C וכיווץ אותה לצורת קרואסון — עכשיו כולם קוראים לה ''כרוסון''!"},"source_index_path":"questlines\\english_kingdom_maya\\_index.yaml"}'::jsonb) on conflict (questline_id, key) do update set position = excluded.position, name = excluded.name, level_required = excluded.level_required, giver_external_id = excluded.giver_external_id, summary = excluded.summary, status = excluded.status, source_path = excluded.source_path, source_metadata = excluded.source_metadata, updated_at = now();
insert into public.quests (questline_id, key, position, name, level_required, giver_external_id, summary, status, source_path, source_metadata) values ((select id from public.questlines where key = 'english_kingdom_maya'), 'q04_dog_ate_homework', 3, 'The Dog Ate My D', 4, 'teacher_maya', 'הכלב של מאיה אכל את האות D משיעורי הבית — עכשיו המילה dog נראית כמו _og, והכלב עדיין מקיא אותיות!', 'complete', 'questlines\english_kingdom_maya\q04_dog_ate_homework.yaml', '{"source_detail":{"giver_npc":"teacher_maya","id":"q04_dog_ate_homework","level_required":4,"name":"The Dog Ate My D","prerequisite":"q03_cat_on_c","summary":"הכלב של מאיה אכל את האות D משיעורי הבית — עכשיו המילה dog נראית כמו _og, והכלב עדיין מקיא אותיות!"},"source_index_path":"questlines\\english_kingdom_maya\\_index.yaml"}'::jsonb) on conflict (questline_id, key) do update set position = excluded.position, name = excluded.name, level_required = excluded.level_required, giver_external_id = excluded.giver_external_id, summary = excluded.summary, status = excluded.status, source_path = excluded.source_path, source_metadata = excluded.source_metadata, updated_at = now();
insert into public.quests (questline_id, key, position, name, level_required, giver_external_id, summary, status, source_path, source_metadata) values ((select id from public.questlines where key = 'english_kingdom_maya'), 'q05_mystery_egg', 4, 'The Mystery Egg', 5, 'teacher_maya', 'ביצה ענקית חוסמת את שער הגן — היא רוצה לשמוע את האות E לפני שהיא נפתחת. ספוילר: בפנים אין תרנגולת, יש אות.', 'complete', 'questlines\english_kingdom_maya\q05_mystery_egg.yaml', '{"source_detail":{"giver_npc":"teacher_maya","id":"q05_mystery_egg","level_required":5,"name":"The Mystery Egg","prerequisite":"q04_dog_ate_homework","summary":"ביצה ענקית חוסמת את שער הגן — היא רוצה לשמוע את האות E לפני שהיא נפתחת. ספוילר: בפנים אין תרנגולת, יש אות."},"source_index_path":"questlines\\english_kingdom_maya\\_index.yaml"}'::jsonb) on conflict (questline_id, key) do update set position = excluded.position, name = excluded.name, level_required = excluded.level_required, giver_external_id = excluded.giver_external_id, summary = excluded.summary, status = excluded.status, source_path = excluded.source_path, source_metadata = excluded.source_metadata, updated_at = now();
insert into public.quests (questline_id, key, position, name, level_required, giver_external_id, summary, status, source_path, source_metadata) values ((select id from public.questlines where key = 'english_kingdom_maya'), 'q06_butterfly_chaos', 5, 'Butterfly Letter Chaos', 6, 'teacher_maya', 'פרפרים מעופפים עם אותיות F על הכנפיים מסביב לגן — כל פעם שהם נוחתים, הם משנים שלט ל-FLY או FRY (צ''יפס מעופף)!', 'complete', 'questlines\english_kingdom_maya\q06_butterfly_chaos.yaml', '{"source_detail":{"giver_npc":"teacher_maya","id":"q06_butterfly_chaos","level_required":6,"name":"Butterfly Letter Chaos","prerequisite":"q05_mystery_egg","summary":"פרפרים מעופפים עם אותיות F על הכנפיים מסביב לגן — כל פעם שהם נוחתים, הם משנים שלט ל-FLY או FRY (צ''יפס מעופף)!"},"source_index_path":"questlines\\english_kingdom_maya\\_index.yaml"}'::jsonb) on conflict (questline_id, key) do update set position = excluded.position, name = excluded.name, level_required = excluded.level_required, giver_external_id = excluded.giver_external_id, summary = excluded.summary, status = excluded.status, source_path = excluded.source_path, source_metadata = excluded.source_metadata, updated_at = now();
insert into public.quests (questline_id, key, position, name, level_required, giver_external_id, summary, status, source_path, source_metadata) values ((select id from public.questlines where key = 'english_kingdom_maya'), 'q07_genius_gate', 6, 'The Genius Gate', 7, 'teacher_maya', 'שער הגאון נעול — הוא מבקש את האות G ושלוש מילים קלות. השער אומר שהוא ''גאון'', אבל לא יודע לפתוח את עצמו.', 'complete', 'questlines\english_kingdom_maya\q07_genius_gate.yaml', '{"source_detail":{"giver_npc":"teacher_maya","id":"q07_genius_gate","level_required":7,"name":"The Genius Gate","prerequisite":"q06_butterfly_chaos","summary":"שער הגאון נעול — הוא מבקש את האות G ושלוש מילים קלות. השער אומר שהוא ''גאון'', אבל לא יודע לפתוח את עצמו."},"source_index_path":"questlines\\english_kingdom_maya\\_index.yaml"}'::jsonb) on conflict (questline_id, key) do update set position = excluded.position, name = excluded.name, level_required = excluded.level_required, giver_external_id = excluded.giver_external_id, summary = excluded.summary, status = excluded.status, source_path = excluded.source_path, source_metadata = excluded.source_metadata, updated_at = now();
insert into public.quests (questline_id, key, position, name, level_required, giver_external_id, summary, status, source_path, source_metadata) values ((select id from public.questlines where key = 'english_kingdom_maya'), 'q08_hat_hunt', 7, 'Maya''s Lost Hat', 8, 'teacher_maya', 'מאיה איבדה את הכובע שלה (HAT) — בלי H, הכובע הפך פשוט ל-_AT, וחתול שמח ישב עליו בגשם.', 'complete', 'questlines\english_kingdom_maya\q08_hat_hunt.yaml', '{"source_detail":{"giver_npc":"teacher_maya","id":"q08_hat_hunt","level_required":8,"name":"Maya''s Lost Hat","prerequisite":"q07_genius_gate","summary":"מאיה איבדה את הכובע שלה (HAT) — בלי H, הכובע הפך פשוט ל-_AT, וחתול שמח ישב עליו בגשם."},"source_index_path":"questlines\\english_kingdom_maya\\_index.yaml"}'::jsonb) on conflict (questline_id, key) do update set position = excluded.position, name = excluded.name, level_required = excluded.level_required, giver_external_id = excluded.giver_external_id, summary = excluded.summary, status = excluded.status, source_path = excluded.source_path, source_metadata = excluded.source_metadata, updated_at = now();
insert into public.quests (questline_id, key, position, name, level_required, giver_external_id, summary, status, source_path, source_metadata) values ((select id from public.questlines where key = 'english_kingdom_maya'), 'q09_letter_island', 8, 'Letter Island Mix-Up', 9, 'teacher_maya', 'על אי האותיות, כל האותיות שלמדתם מתערבבות בערבוביה — האי חושב ש-I נראית כמו 1 ורוצה שתסדרו את הבלגן.', 'complete', 'questlines\english_kingdom_maya\q09_letter_island.yaml', '{"source_detail":{"giver_npc":"teacher_maya","id":"q09_letter_island","level_required":9,"name":"Letter Island Mix-Up","prerequisite":"q08_hat_hunt","summary":"על אי האותיות, כל האותיות שלמדתם מתערבבות בערבוביה — האי חושב ש-I נראית כמו 1 ורוצה שתסדרו את הבלגן."},"source_index_path":"questlines\\english_kingdom_maya\\_index.yaml"}'::jsonb) on conflict (questline_id, key) do update set position = excluded.position, name = excluded.name, level_required = excluded.level_required, giver_external_id = excluded.giver_external_id, summary = excluded.summary, status = excluded.status, source_path = excluded.source_path, source_metadata = excluded.source_metadata, updated_at = now();
